/// Memory / instruction files contributing to the system prompt
/// hierarchy — one list, shared by `memory_files` and
/// `system_prompt.memory_files`.
const OPENCODE_MEMORY_FILES: &[PathTemplate] = &[PathTemplate::Static("AGENTS.md")];

/// Builds the resource portability descriptor served through
/// `resource_support_fn` (heap-backed, so it lives behind the `LazyLock`
/// rather than in the `ProviderInfo` static).
fn build_resource_support() -> ProviderCapabilities {
    ProviderCapabilities {
        provider: Provider::OpenCode,
        skills: ResourceSupport {
            level: SupportLevel::Full,
            format: Some(ResourceFormat::Markdown),
            repo_path: Some(PathBuf::from(".opencode/skills")),
            user_path: Some(PathBuf::from(".config/opencode/skills")),
            also_reads_from: vec![PathBuf::from(".claude/skills"), PathBuf::from(".agents/skills")],
            notes: None,
            properties: Some(ResourcePropertySchema::new(
                &["name", "description"],
                &["license", "compatibility", "metadata"],
                "claudine/docs/cross-referencing/opencode.md",
            )),
        },
        commands: ResourceSupport {
            level: SupportLevel::Full,
            format: Some(ResourceFormat::Markdown),
            repo_path: Some(PathBuf::from(".opencode/commands")),
            user_path: Some(PathBuf::from(".config/opencode/commands")),
            also_reads_from: vec![],
            notes: None,
            properties: Some(ResourcePropertySchema::new(
                &[],
                &["description", "template", "agent", "model", "subtask"],
                "claudine/docs/cross-referencing/opencode.md",
            )),
        },
        agents: ResourceSupport {
            level: SupportLevel::Full,
            format: Some(ResourceFormat::Markdown),
            repo_path: Some(PathBuf::from(".opencode/agents")),
            user_path: Some(PathBuf::from(".config/opencode/agents")),
            also_reads_from: vec![],
            notes: None,
            properties: Some(ResourcePropertySchema::new(
                &["description"],
                &[
                    "mode",
                    "model",
                    "temperature",
                    "top_p",
                    "tools",
                    "permission",
                    "steps",
                    "color",
                    "hidden",
                    "disable",
                    "prompt",
                ],
                "claudine/docs/cross-referencing/opencode.md",
            )),
        },
        scripts: ResourceSupport {
            level: SupportLevel::Full,
            format: Some(ResourceFormat::Executable),
            repo_path: Some(PathBuf::from(".opencode/scripts")),
            user_path: Some(PathBuf::from(".config/opencode/scripts")),
            also_reads_from: vec![],
            notes: None,
            properties: None,
        },
        skill_frontmatter: SkillFrontmatter {
            name: true,
            description: true,
            license: true,
            compatibility: true,
            metadata: true,
            allowed_tools: false,
            user_invocable: false,
            disable_model_invocation: false,
        },
    }
}
